import fs from 'fs';
import path from 'path';
import { z } from 'zod';
import {
  GuidanceDocumentSchema,
  guidanceWarning,
  type GuidanceWarning,
} from '../../types/guidance';
import { getConfigManager } from '../../services/ConfigManager';
import type { CliIO } from '../io';
import { okResult, type CliCommandResult } from '../envelope';
import {
  parseCommandContext,
  isCommandResult,
  commandErrorResult,
} from './shared';
import {
  ensureProjectRuntime,
  PROJECT_RUNTIME_FLAG_SPEC,
  validateProjectOpen,
} from './open';
import {
  currentLibraryRoot,
  type ProjectLibrary,
} from '../../services/ProjectLibrary';
import { ProjectRegistry } from '../../services/ProjectRegistry';
import { ensureHub, requestHub } from '../../library/HubClient';
import { createLibraryLaunchUrl } from '../../library/browserLaunch';
import { requestBrowserOpen } from '../browser';
import { signInThroughBrowser } from '../browserSignIn';
import type { AuthService } from '../../services/AuthService';
import { errorMessage } from '../../utils/errorMessage';

interface LibraryOpenOptions {
  env?: NodeJS.ProcessEnv;
  openBrowser?: (url: string) => Promise<unknown>;
  authService?: AuthService;
}

const GUIDANCE_TIMEOUT_MS = 5_000;

const OPEN_FLAG_SPEC = {
  ...PROJECT_RUNTIME_FLAG_SPEC,
  'no-browser': { takesValue: false },
};

const isProjectOpen = (args: {
  projectPath: string;
  isExplicit: boolean;
  isRegistered: boolean;
}): boolean =>
  args.isExplicit ||
  args.isRegistered ||
  ['package.json', 'index.html', '.rivet/variants', '.rivet/store.git'].some(
    (marker) => fs.existsSync(path.join(args.projectPath, marker)),
  );

export const handleLibraryOpen = async (
  args: string[],
  io: CliIO,
  options: LibraryOpenOptions = {},
): Promise<CliCommandResult> => {
  const env = options.env ?? process.env;
  const context = parseCommandContext('open', args, OPEN_FLAG_SPEC, env);
  if (isCommandResult(context)) return context;
  const root = currentLibraryRoot(env);
  const isBrowserDisabled = context.flags.values['no-browser'] === true;
  const registry = await ProjectRegistry.open(root);
  try {
    const hasProject = isProjectOpen({
      projectPath: context.projectPath,
      isExplicit: context.flags.values.project !== undefined,
      isRegistered: Boolean(registry.findByPath(context.projectPath)),
    });
    if (hasProject) {
      const validation = await validateProjectOpen({
        context,
        io,
        signIn: () =>
          signInThroughBrowser({
            command: 'open',
            io,
            isBrowserDisabled,
            env,
            editor: context.handoff?.agent,
            authService: options.authService,
            launch: options.openBrowser,
          }),
      });
      if (validation) return validation;
    }
    const accountId = getConfigManager().getUserId();
    const hub = await ensureHub({
      root,
      env: {
        ...env,
        ...(context.flags.values['no-telemetry'] === true
          ? { RIVET_LIBRARY_TELEMETRY: '0' }
          : {}),
      },
    });
    let data: Record<string, unknown> = { mode: 'library' };
    let projectId: string | undefined;
    if (hasProject) {
      const prepared = await requestHub<
        Awaited<ReturnType<ProjectLibrary['prepare']>>
      >({
        hub,
        endpoint: '/projects',
        body: { projectPath: context.projectPath },
      });
      projectId = prepared.project.id;
      const opened = await ensureProjectRuntime(context, io, { env });
      if (!opened.envelope.ok) return opened;
      data = {
        ...(opened.envelope.data as Record<string, unknown>),
        projectEditorUrl: (opened.envelope.data as Record<string, unknown>)
          .editorUrl,
        migration: prepared.migration,
      };
    }
    const projectSuffix = projectId
      ? `/projects/${encodeURIComponent(projectId)}`
      : '';
    const editorUrl = await createLibraryLaunchUrl({
      hub,
      path: `/rivet/library${projectSuffix}`,
      callerAgent: context.handoff?.agent,
    });
    const browser = await requestBrowserOpen({
      url: editorUrl,
      urlField: 'editorUrl',
      isBrowserDisabled,
      io,
      launch: options.openBrowser,
    });
    let guidanceResult:
      | {
          guidance: z.infer<typeof GuidanceDocumentSchema>[];
          guidanceWarning?: GuidanceWarning;
        }
      | { guidance: []; guidanceStatus: 'signed_out' }
      | { guidanceError: string };
    try {
      if (getConfigManager().getUserId() !== accountId)
        throw new Error('Rivet account changed while opening the editor.');
      if (!accountId) {
        guidanceResult = { guidance: [], guidanceStatus: 'signed_out' };
      } else {
        const resolved = await requestHub({
          hub,
          endpoint: '/guidance/resolutions',
          method: 'POST',
          body: {},
          expectedAccountId: accountId,
          timeoutMs: GUIDANCE_TIMEOUT_MS,
        });
        if (getConfigManager().getUserId() !== accountId)
          throw new Error('Rivet account changed while opening the editor.');
        const resolution = z
          .object({
            accountId: z.string().min(1),
            guidance: z.array(GuidanceDocumentSchema),
          })
          .parse(resolved);
        if (resolution.accountId !== accountId)
          throw new Error('Rivet account changed while loading saved context.');
        const warning = guidanceWarning(resolution.guidance);
        guidanceResult = {
          guidance: resolution.guidance,
          ...(warning ? { guidanceWarning: warning } : {}),
        };
      }
    } catch (error) {
      guidanceResult = {
        guidanceError: `Saved context could not load. ${errorMessage(error, 'Context is unavailable.')} Run rivet context resolve before generation, or explicitly disable saved guidance for that request.`,
      };
    }
    return okResult('open', {
      ...data,
      ...guidanceResult,
      projectId: projectId ?? null,
      editorUrl,
      browser,
    });
  } catch (error) {
    return commandErrorResult('open', error);
  } finally {
    registry.close();
  }
};
